 const activeGroup=moduleDefs[currentModule]?.group||'main';
 $('adminNav').innerHTML=groups.map(g=>`<section class="admin-nav-section ${g.key===activeGroup?'open':''}" data-nav-group="${escapeHTML(g.key)}"><button type="button" class="admin-nav-group-toggle" aria-expanded="${g.key===activeGroup?'true':'false'}"><span>${escapeHTML(g.label)}</span><span aria-hidden="true">⌄</span></button><div class="admin-nav-items">${g.items.map(([k,m])=>`<button type="button" data-module="${k}">${escapeHTML(m.label)}</button>`).join('')}</div></section>`).join('');
 $('adminNav').querySelectorAll('[data-module]').forEach(b=>b.addEventListener('click',()=>renderAdminModule(b.dataset.module)));
