async function permanentDeleteRpc(rpc,id,label,onSuccess){
 if(!isSuperAdmin()){adminMessage('Permanent deletion requires a Super Administrator.','error');return false}
 const confirmation=prompt(`Permanent deletion cannot be undone. Type DELETE to permanently remove ${label}.`);if(confirmation===null)return false;if(confirmation.trim().toUpperCase()!=='DELETE'){adminMessage('Permanent deletion cancelled because DELETE was not entered.','error');return false}
 const args={p_confirmation:'DELETE'};if(rpc==='permanent_delete_contact_message')args.p_message_id=id;else if(rpc==='permanent_delete_donation_intent')args.p_intent_id=id;else if(rpc==='permanent_delete_donor')args.p_donor_id=id;else if(rpc==='permanent_delete_verified_donation')args.p_donation_id=id;else if(rpc==='permanent_delete_newsletter_subscriber')args.p_subscriber_id=id;else args.p_id=id;
 const {data,error}=await neonClient.rpc(rpc,args);if(error){adminMessage('Permanent deletion blocked: '+error.message,'error');return false}adminMessage(`${label} permanently removed.`);if(onSuccess)await onSuccess(data);return true
}
